{
  "candidates": [
    {
      "subpart": "PPPP",
      "name": "Surface coating of plastic parts and products",
      "criteria": [
        {
          "citation": "63.4481(a)(1)",
          "check": "Whether the solvent-welding step is an application of a 'surface coating' to a substrate (i.e., an application of a material to a part, including associated activities such as surface preparation or cleaning) as defined in §63.4481(a)(1)."
        },
        {
          "citation": "63.4581",
          "check": "Whether the material applied (methylene chloride or a formulation containing it) is a 'coating' or an 'adhesive/adhesive coating' (a chemical substance applied for the purpose of bonding two surfaces) as defined in §63.4581."
        },
        {
          "citation": "63.4481(b)",
          "check": "Whether the affected source uses 378 liters (100 gallons) per year or more of coatings that contain HAP in the surface coating of plastic parts and products and is a major source (or located at/part of a major source) as required by §63.4481(b)."
        },
        {
          "citation": "63.4482(b)",
          "check": "Whether the solvent-welding lines and their associated storage, mixing, conveyance, and waste-handling equipment fall within the affected source definition for surface coating of plastic parts and products in §63.4482(b)."
        }
      ],
      "you_should_check": [
        "Is the methylene-chloride application performed specifically to bond plastic parts (i.e., functioning as an adhesive) versus solely as a cleaning/degreasing step?",
        "How the material is classified by the supplier/manufacturer (coating/adhesive vs. cleaning solvent) and manufacturer's formulation data showing organic HAP content and solids.",
        "Annual volume (liters or gallons per year) of the HAP-containing material used in these solvent-welding lines (include the six new lines in the projection).",
        "Confirm facility major-source status for HAP (single HAP ≥10 tpy or combined HAP ≥25 tpy) and that the parts being treated are plastic parts/products (e.g., medical device plastic components)."
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "XXXXXX",
      "name": "Area-source Metal Fabrication and Finishing NESHAP",
      "criteria": [
        {
          "citation": "63.11514(a)",
          "check": "Do you own or operate an area source that is primarily engaged in operations in one of the nine metal fabrication and finishing source categories listed in §63.11514(a)(1)–(9)?"
        },
        {
          "citation": "63.11522",
          "check": "Is at least 50 percent of facility production (using the previous continuous 12 months) in one of those nine source categories (i.e., does the facility meet the 'primarily engaged' definition)?"
        },
        {
          "citation": "63.11514(b)",
          "check": "Does the facility use materials that contain MFHAP (cadmium, chromium, lead, or nickel ≥ 0.1% by weight, or manganese ≥ 1.0% by weight as shown by manufacturer/supplier formulation data or MSDS) or have the potential to emit MFHAP?"
        },
        {
          "citation": "63.11514(b)(1)-(5)",
          "check": "Does the facility perform any of the affected-source activities listed (dry abrasive blasting, machining, dry grinding/dry polishing with machines, spray painting, or welding) on materials that contain or could emit MFHAP?"
        }
      ],
      "you_should_check": [
        "Whether the facility is an area source (and not a major source) under applicable definitions.",
        "The previous continuous 12 months' production mix to confirm ≥50% production within one of the nine listed categories (e.g., Electrical and Electronic Equipment Finishing or Fabricated Metal Products).",
        "Which specific processes are performed on-site (dry abrasive blasting, machining, dry grinding/polishing with machines, spray painting, welding).",
        "Material formulation/MSDS data showing metal content (wt% of Cd, Cr, Pb, Ni, Mn) to determine if materials contain MFHAP above the thresholds in §63.11514(b)."
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "DDDD",
      "name": "Plywood and Composite Wood Products (PCWP) NESHAP",
      "criteria": [
        {
          "citation": "63.2231(a)",
          "check": "Whether you own or operate a PCWP manufacturing facility (a facility that manufactures plywood and/or composite wood products, including facilities that manufacture dry veneer and lumber kilns located at any facility)."
        },
        {
          "citation": "63.2231(b)",
          "check": "Whether the PCWP manufacturing facility is located at a major source of HAP (any single HAP ≥ 9.07 megagrams/10 tons per year or combined HAPs ≥ 22.68 megagrams/25 tons per year)."
        },
        {
          "citation": "63.2232(b)",
          "check": "Whether the affected source would include your lumber kilns as part of the collection of dryers and drying operations and other process units associated with PCWP manufacturing (the affected source explicitly includes lumber kilns at PCWP facilities and at any other kind of facility)."
        },
        {
          "citation": "63.2233(c)",
          "check": "If you are currently an area source that increases emissions or potential to emit such that it becomes a major source of HAP, whether you must be in compliance with this subpart by October 1, 2007 or upon initial startup of your affected source as a major source, whichever is later."
        }
      ],
      "you_should_check": [
        "Do you manufacture plywood or composite wood products (or only lumber) at this site, or otherwise meet the PCWP facility description in 63.2231(a)?",
        "Is your facility a major source for HAPs (is methanol or any single HAP ≥ 10 tpy, or total HAPs ≥ 25 tpy) based on potential to emit or actual emissions?",
        "Are the lumber dry kilns at this site part of the PCWP affected source as defined (i.e., dryers/drying operations associated with manufacturing)?",
        "If you become a major source, what is the effective date of that reclassification and has the compliance date for the subpart already passed?"
      ]
    },
    {
      "subpart": "A",
      "name": "General Provisions (Part 63) — applicability and affected source definition",
      "criteria": [
        {
          "citation": "63.1(b)(1)",
          "check": "Whether you are the owner or operator of a stationary source that emits or has the potential to emit any HAP and is subject to any standard, limitation, prohibition, or other federally enforceable requirement established pursuant to part 63."
        },
        {
          "citation": "63.1(c)(6)(i)(B)",
          "check": "Whether an area source that previously was a major source and becomes a major source again is subject to the applicable major source requirements established under this part immediately upon becoming a major source again, provided the compliance date for the major source requirements has passed."
        },
        {
          "citation": "63.2",
          "check": "Whether the equipment/operations (e.g., kilns, dryers) qualify as an 'affected source' under part 63 as the collection of equipment and activities within a single contiguous area and under common control that is included in a section 112(c) source category."
        }
      ],
      "you_should_check": [
        "Does your facility emit or have the potential to emit HAPs such that it falls within part 63 applicability (per 63.1(b)(1))?",
        "If reclassified to major by a permit revision, what is the effective date of that reclassification (i.e., when do you 'become' a major source) and have the compliance dates for applicable standards passed?",
        "Is the set of equipment/operations at issue (kilns/dryers) contiguous and under common control such that they meet the 'affected source' definition in 63.2?"
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "PPPPPP",
      "name": "Lead acid battery manufacturing (NESHAP)",
      "criteria": [
        {
          "citation": "63.11421(a)",
          "check": "Whether the plant is a lead acid battery manufacturing or component manufacturing plant that is an area source (if not, this subpart does not apply)."
        },
        {
          "citation": "63.11421(b)",
          "check": "Whether the new Humidity Curing and Drying Oven Chambers are part of the affected source at the plant (the affected source includes 'any other lead-emitting operation associated with the lead acid battery manufacturing plant')."
        },
        {
          "citation": "63.11421(b)(1)-(4)",
          "check": "Whether the affected source (the plant) is classified as an existing or new affected source based on the applicable construction/reconstruction dates in those paragraphs."
        },
        {
          "citation": "63.11423(c)(1)",
          "check": "For an existing affected source, whether a prior performance test using the same methods exists and either no process changes have occurred since that test or you can demonstrate the prior test (with or without adjustments) reliably demonstrates compliance for the new ovens."
        }
      ],
      "you_should_check": [
        "Plant status/date of commencement (to determine existing vs. new per 63.11421).",
        "Whether the new ovens emit lead and are physically part of the affected source.",
        "Existence, date, methods, and results of prior performance tests for the existing ovens.",
        "Whether process/equipment changes since the prior test could affect applicability of prior test results for the new ovens."
      ]
    },
    {
      "subpart": "A",
      "name": "General provisions — performance testing (Subpart A)",
      "criteria": [
        {
          "citation": "63.7(a)(2)",
          "check": "Whether you are required to perform a performance test and, if so, that it must be conducted within 180 days of the applicable compliance date unless a waiver is obtained under this section."
        },
        {
          "citation": "63.7(b)(1)",
          "check": "If you plan to perform a performance test, you must notify the Administrator in writing at least 60 calendar days before the initially scheduled test date (allowing the Administrator to review/attend)."
        },
        {
          "citation": "63.7(c)(2)(i)",
          "check": "Whether you have prepared (and, if requested, will submit) a site-specific test plan including test program summary, schedule, data quality objectives, and QA program prior to conducting a required test."
        },
        {
          "citation": "63.7(c)(2)(iii)",
          "check": "Whether you can implement the required test method performance audit (blind audit samples) and include audit sample results with the performance test (or document commercial unavailability per the provision)."
        }
      ],
      "you_should_check": [
        "Whether you already have an approved waiver under 63.7 for the existing ovens and the scope/terms of that waiver.",
        "Planned test schedule and ability to provide 60-day notice and a site-specific test plan if testing is performed.",
        "Ability to obtain and use audit samples as required by the QA provisions of 63.7(c).",
        "Whether you intend to rely on a waiver under 63.7 for the new ovens or to perform a new/combined performance test."
      ]
    },
    {
      "subpart": "YY",
      "name": "Extension of compliance and waivers/alternatives",
      "criteria": [
        {
          "citation": "63.1112(a)(2)(ii)",
          "check": "Whether an extension may be justified because the source previously installed BACT or LAER for the same pollutant before promulgation (which can support an extension under the 'other reductions' provision)."
        },
        {
          "citation": "63.1112(a)(4)(A)-(B)",
          "check": "Whether you will request an extension of compliance (including performance testing) in writing and meet any applicable submittal deadlines specified in those paragraphs (timing depends on circumstances described there)."
        },
        {
          "citation": "63.1112(a)(6)(i)-(D)",
          "check": "Whether your written request includes the required contents: description of controls, a compliance schedule with milestones, interim control steps, and whether you are also requesting extension of performance testing."
        },
        {
          "citation": "63.1112(a)(9)-(10)",
          "check": "Whether you understand the Administrator may grant an extension and that any granted extension will be written and specify the affected sources covered, termination date, dates for steps toward compliance, and whether performance testing requirements are included."
        }
      ],
      "you_should_check": [
        "Whether the facility has previously obtained an extension/waiver and the terms of that document.",
        "Whether the facility installed BACT or LAER (and dates) prior to promulgation to qualify under (a)(2)(ii) or (a)(5) if applicable.",
        "Prepare the written request contents per 63.1112(a)(6) and confirm timing against the applicable compliance date.",
        "Whether you are requesting that the Administrator extend or waive the performance testing requirement for the new ovens (explicitly state this in the request)."
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "63.460",
      "name": "Applicability (Subpart T)",
      "criteria": [
        {
          "citation": "63.460(a)",
          "check": "Determine whether the machine is a batch vapor, in-line vapor, in-line cold, or batch cold solvent cleaning machine that uses any listed halogenated HAP (methylene chloride, perchloroethylene, trichloroethylene, 1,1,1‑trichloroethane, carbon tetrachloride, or chloroform) at a total concentration greater than 5 percent by weight as a cleaning or drying agent."
        },
        {
          "citation": "63.460(a)",
          "check": "Confirm the activity is not exempt wipe‑cleaning (e.g., rag or spray wipe), which is not covered by this subpart."
        }
      ],
      "you_should_check": [
        "Identity and concentration (% by weight) of solvents used in the machine",
        "Whether the unit is a batch vapor, in‑line (continuous) unit, batch cold (immersion) or in‑line cold unit",
        "Whether cleaning is performed by wiping or by a solvent‑immersion/vapor process",
        "Whether the unit is a continuous web cleaning machine"
      ]
    },
    {
      "subpart": "63.463",
      "name": "Batch vapor and in‑line cleaning machine standards",
      "criteria": [
        {
          "citation": "63.463(a)",
          "check": "If the machine is a batch vapor or an in‑line solvent cleaning machine subject to this subpart, these design and operational requirements apply to existing and new units."
        },
        {
          "citation": "63.463(a)(6)",
          "check": "If the unit is a vapor cleaning machine, determine whether it has (or must have) a primary condenser (requirement for vapor machines)."
        },
        {
          "citation": "63.463(b)",
          "check": "If the unit is a batch vapor machine, determine the solvent/air interface area and whether it is ≤1.21 m2 or >1.21 m2 because that threshold dictates which control options or emission demonstration requirements apply."
        },
        {
          "citation": "63.463(c)",
          "check": "If the unit is an in‑line cleaning machine, determine whether it is new or existing because the standard (control combinations or idling emission limit) differs for new versus existing in‑line machines."
        }
      ],
      "you_should_check": [
        "Whether the machine operates with a solvent vapor zone (i.e., is a vapor cleaning machine) per the definition of solvent/air interface (63.461)",
        "Measure or estimate the solvent/air interface area (m2)",
        "Whether the machine is batch vs in‑line, and whether it is new or existing",
        "Whether the unit has a primary condenser and other design features (covers, freeboard ratio, automated handling) referenced in 63.463(a)"
      ]
    },
    {
      "subpart": "63.462",
      "name": "Batch cold cleaning machine standards",
      "criteria": [
        {
          "citation": "63.462(a)",
          "check": "If the machine is an immersion batch cold solvent cleaning machine, determine whether it is subject to the immersion‑machine requirements (tightly fitting cover plus either a ≥1.0 in water layer or a freeboard ratio ≥0.75)."
        },
        {
          "citation": "63.462(b)",
          "check": "If the machine is a remote‑reservoir batch cold cleaning machine, determine whether a tightly fitting cover over the solvent sump that is closed except during cleaning is employed, since that is the required design practice."
        }
      ],
      "you_should_check": [
        "Whether parts are immersed in liquid solvent during cleaning (immersion batch cold) or solvent is applied from a remote reservoir",
        "Whether the cold stage is heated non‑boiling solvent (falls under 'cold cleaning machine' definition)",
        "Whether the machine has a tight cover and either a water layer or sufficient freeboard ratio (0.75) if immersion"
      ]
    },
    {
      "subpart": "63.464",
      "name": "Alternative standards (emissions‑based options)",
      "criteria": [
        {
          "citation": "63.464(a)(1)",
          "check": "If the cleaning machine has a solvent/air interface, you may elect the alternative standard that requires keeping a solvent addition/deletion log and ensuring emissions do not exceed the table 5 limits (kg/m2/month)."
        },
        {
          "citation": "63.464(a)(2)",
          "check": "If the cleaning machine is a batch vapor machine and does not have a solvent/air interface, you may elect the alternative standard that requires logging solvent additions/deletions and meeting the cleaning‑capacity‑based emission limits in table 6 or equation 1 (use table 6 or eq.1 depending on cleaning capacity ≤ or > 2.95 m3)."
        },
        {
          "citation": "63.464(d)",
          "check": "If the unit is a continuous web cleaning machine, an alternative demonstration of overall cleaning system control efficiency ≥70% may be used in lieu of §63.463."
        }
      ],
      "you_should_check": [
        "Whether the machine has a solvent/air interface (per 63.461) or is a batch vapor without an interface",
        "The cleaning capacity (cubic meters) if there is no solvent/air interface to determine whether table 6 or equation 1 applies",
        "Whether you intend to comply via the alternative emissions/logging approach instead of meeting §63.463 design/operational requirements",
        "If continuous web, whether you will demonstrate ≥70% overall control efficiency"
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "GG",
      "name": "Aerospace manufacturing and rework NESHAP",
      "criteria": [
        {
          "citation": "63.741(a)",
          "check": "Whether the facility engages in the manufacture or rework of aerospace vehicles or components and is a major source as defined in §63.2 (if both are true, Subpart GG can apply)."
        },
        {
          "citation": "63.741(c)(1)(i)-(iii)",
          "check": "Whether the cleaning activities at the facility include hand‑wipe cleaning, spray gun cleaning, or flush cleaning, since each of those cleaning operation types is listed as an affected source under this subpart."
        },
        {
          "citation": "63.744(e)(4) and 63.744(e)(5)",
          "check": "Whether specific cleaning tasks fall within the explicit exemptions: cleaning of electronic parts and assemblies containing electronic parts (63.744(e)(4)); and cleaning of aircraft fluid systems exposed to the fluid, including hydraulic fluid systems (63.744(e)(5))."
        },
        {
          "citation": "63.744(a)–(d) and 63.752(b)(1)–(5)",
          "check": "If a cleaning operation is not exempt, which compliance paths apply: (a) housekeeping/closed‑container requirements; (b) hand‑wipe solvent limits (meet Table 1 composition, or composite vapor pressure ≤45 mm Hg at 20 °C, or approved ≥60% volume reduction plan) per 63.744(b); (c) required spray‑gun cleaning techniques (enclosed system, nonatomized, disassembled‑in‑vat, or atomizing into a capture device) per 63.744(c); (d) flush cleaning into closed/enclosed collection systems per 63.744(d); and required solvent/usage/leak records per 63.752(b)."
        }
      ],
      "you_should_check": [
        "Whether your facility is a major source of HAP (to trigger applicability per 63.741(a)).",
        "For each cleaning task, whether it is hand‑wipe, spray‑gun, or flush cleaning as defined in 63.742 and 63.741(c)(1).",
        "Whether the specific tasks are covered by the exemptions in 63.744(e)(4) (electronic parts/assemblies) or 63.744(e)(5) (aircraft fluid systems/hydraulic fluid systems).",
        "Cleaning solvent properties and formulations (HAP content, whether qualifies as non‑HAP material, composite vapor pressure, or meets Table 1 composition) and monthly/annual usage records needed to support the chosen compliance option per 63.744(b) and 63.752(b)."
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "MM",
      "name": "Kraft/soda smelt dissolving tank (Subpart MM) monitoring",
      "criteria": [
        {
          "citation": "63.864(e)(10)",
          "check": "Whether you operate a kraft or soda smelt dissolving tank equipped with a wet scrubber (subject to the CPMS requirements in this section)."
        },
        {
          "citation": "63.864(e)(10)(i)",
          "check": "Whether the continuous pressure-drop monitoring device is certified by the manufacturer accurate to within ±2 inches of water gauge (±500 pascals)."
        },
        {
          "citation": "63.864(e)(10)(iii)",
          "check": "Whether the smelt dissolving tank uses a dynamic scrubber that operates at ambient pressure (which would allow use of fan amperage or RPM as an alternative to pressure-drop measurement)."
        },
        {
          "citation": "63.864(j)(1)-(2); 63.864(j)(5)(i)(B)",
          "check": "Whether minimum operating limits (including minimum scrubber pressure drop) were established based on values recorded during the initial or a previous performance test (set as the lowest 1‑hour average pressure drop associated with compliant test runs)."
        }
      ],
      "you_should_check": [
        "Is the unit a kraft/soda smelt dissolving tank covered by Subpart MM?",
        "Do you have initial or prior certified performance test data (1‑hour averages) used to set the current pressure‑drop limit?",
        "Does your installed CPMS meet the ±2 in. w.c. accuracy requirement, or is your scrubber an ambient‑pressure dynamic scrubber (so fan amperage/RPM could be used)?",
        "Do you plan to rely on historical/performance‑test data versus conducting a new performance test to set a lower limit?"
      ]
    },
    {
      "subpart": "TTTTT",
      "name": "Wet scrubber operating limits (Subpart TTTTT)",
      "criteria": [
        {
          "citation": "63.9890(b)",
          "check": "Whether the wet scrubber is applied to meet any PM, PM10, chlorine, HCl, or dioxins/furans emission limit in Table 1 to this subpart, in which case you must maintain hourly average pressure drop and liquid flow at or above the minimum level established during the initial or subsequent performance test."
        },
        {
          "citation": "63.9916(a)",
          "check": "Whether you used the CPMS required in §63.9920 to measure and record pressure drop and scrubber water flow rate at least every 15 minutes during each run of the particulate matter performance test."
        },
        {
          "citation": "63.9916(b)",
          "check": "Whether the operating limits were established as the lowest average pressure drop and flow rate from any of the three compliant individual test runs (i.e., limits come from performance‑test run averages)."
        },
        {
          "citation": "63.9920",
          "check": "Whether you are subject to the continuous monitoring requirement to monitor hourly average pressure drop and liquid flow using a CPMS at all times."
        }
      ],
      "you_should_check": [
        "Is your wet scrubber used to meet any Table 1 emission limits listed in Subpart TTTTT (PM, PM10, chlorine, HCl, or dioxins/furans)?",
        "Do you have CPMS data (15‑min measurements) from the initial or subsequent PM performance tests (three runs) that established the current operating limits?",
        "Have you sought to change operating limits without conducting a new performance test (note the procedures for revising limits require a performance test)?",
        "Is the CPMS and the averaging (hourly/hourly average) being performed per the subpart's monitoring requirements?"
      ]
    },
    {
      "subpart": "RRRRR",
      "name": "Wet scrubber operating limits (Subpart RRRRR)",
      "criteria": [
        {
          "citation": "63.9622(a)(1)",
          "check": "Whether the CPMS required in §63.9631(b) was used to measure and record pressure drop and scrubber water flow rate every 15 minutes during each run of the particulate matter performance test."
        },
        {
          "citation": "63.9622(a)(2)",
          "check": "Whether operating limits were established as the lowest average pressure drop and lowest average scrubber water flow rate corresponding to any of the three individual test runs (i.e., limits derived from performance‑test run averages)."
        },
        {
          "citation": "63.9622(a)(3)",
          "check": "Whether any special exception applies (e.g., using historical certified performance‑test data to set a lower average pressure drop for a rod‑deck venturi scrubber on an indurating furnace)."
        },
        {
          "citation": "63.9622(f)",
          "check": "Whether you propose to change operating limits without following the change procedures (notification and conducting a performance test) required to revise limits."
        }
      ],
      "you_should_check": [
        "Is your wet scrubber subject to performance testing under the RRRRR subpart (i.e., to §63.9620 and operating limits in §63.9590(b)(1))?",
        "Do you have the required CPMS 15‑minute performance‑test data (three runs) that established the current pressure‑drop limit?",
        "Are you attempting to lower the pressure‑drop operating limit without submitting notification and conducting a new performance test?",
        "Does any historical certified performance test exception apply to your scrubber type?"
      ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "X",
      "name": "Secondary Lead Smelting",
      "criteria": [
        {
          "citation": "63.541(a)",
          "check": "Do you own or operate any affected source at a secondary lead smelter (e.g., blast, reverberatory, rotary, or electric furnaces; refining kettles; agglomerating furnaces; dryers; process fugitive emissions sources; buildings containing lead-bearing materials; or fugitive dust sources)?"
        },
        {
          "citation": "63.542",
          "check": "Does your facility meet the definition of a 'secondary lead smelter' and perform 'smelting' (chemical reduction of lead compounds to elemental lead or lead alloys in high‑temperature furnaces operated above 980 °C)?"
        },
        {
          "citation": "63.543(a),(b)",
          "check": "Are lead emissions from process vents subject to the Subpart X concentration limits (existing sources: ≤1.0 mg lead/m3 per vent and flow‑weighted average ≤0.20 mg lead/m3; new sources (post‑May 19, 2011): ≤0.20 mg lead/m3 per vent)?"
        },
        {
          "citation": "63.543(a)(1)–(4)",
          "check": "Can you demonstrate compliance by measuring vent concentrations and flow rates and calculating the flow‑weighted average (12‑month rolling average calculated monthly using most recent test data or CEMS data per Equation 1)?"
        }
      ],
      "you_should_check": [
        "Whether your CRT glass recycling involves smelting that reduces lead compounds to elemental lead/lead alloys at >980 °C.",
        "Which equipment/processes at your site match the affected source list in 63.541(a) (furnaces, kettles, dryers, process vents, buildings with lead‑bearing materials, fugitive dust sources).",
        "Measured lead concentrations and volumetric flow rates for each process vent (or CEMS data) to compute per‑vent and flow‑weighted average concentrations.",
        "Whether your construction/reconstruction date makes you a 'new source' (subject to the 0.20 mg/m3 per‑vent limit) or an existing source."
    ]
    }
  ]
}

{
  "candidates": [
    {
      "subpart": "WW",
      "name": "Storage vessels with floating roofs (Subpart WW)",
      "criteria": [
        {
          "citation": "63.1065(a)",
          "check": "Is a record being kept of each storage vessel's dimensions, an analysis of its capacity, and identification of the liquid stored (records kept as long as the liquid is stored)?"
        },
        {
          "citation": "63.1065(b)(1)",
          "check": "Are inspection results recorded for each floating roof inspection, including vessel identification, inspection date, and, if failures occur, descriptions of failures, repairs and repair dates?"
        },
        {
          "citation": "63.1065(b)(2)",
          "check": "Are EFR (external floating roof) seal gap measurements recorded and do those records include the raw data obtained and any calculations performed?"
        },
        {
          "citation": "63.1065",
          "check": "Are records kept in a manner that they can be readily accessed within 24 hours and are they retained in hard copy or computer-readable form?"
        }
      ],
      "you_should_check": [
        "Which tanks are subject to Subpart WW (external floating roofs) at this facility",
        "Whether you perform seal-gap measurements and inspections described in 63.1065(b)",
        "Whether the retained records include the raw measurement data (field notes) and calculations",
        "Whether records are stored in a form that is readily accessible within 24 hours (paper or electronic) and for the durations required"
      ]
    },
    {
      "subpart": "A",
      "name": "General provisions — recordkeeping (Subpart A)",
      "criteria": [
        {
          "citation": "63.10(b)(1)",
          "check": "Is the facility an affected source under Part 63 required to maintain files of all information required by this part in a form suitable and readily available for inspection and review, retained at least 5 years, with the most recent 2 years on site?"
